import type { ToolCategory, LegacyComponentKey } from "./tools-registry";

export interface GuideSection { heading: string; paragraphs: string[] }

function guide(...sections: [string, string][]): GuideSection[] {
  return sections.map(([heading, text]) => ({ heading, paragraphs: text.split("\n\n") }));
}

export const toolGuides: Record<LegacyComponentKey, GuideSection[]> = {
  "background-remover": guide(
    ["Start with a clear subject", `A product photo with a plain wall behind it is a good first test. Choose a supported image, then start background removal. The tool separates the foreground from the background and returns a cutout you can inspect before exporting. It works best when the subject has a clear outline and is visually distinct from its surroundings. Keep the original image so you can compare details such as hair, handles, transparent surfaces, and shadows. For a catalog image, leave space around the subject rather than cropping tightly before inference. That surrounding context can help you judge whether the final outline remains complete. Removing a background changes the image; it is not a lossless operation or a guarantee that every edge will be correctly identified.`],
    ["Understand the first run", `The first operation downloads the AI model and its browser runtime. That can take longer than the actual removal, especially on a slow connection. Progress messages distinguish asset loading from image processing, so leave the tab open while the operation completes. Model downloads are network requests to IMG.LY, but your chosen image is processed on your device rather than uploaded to a removal service. Later operations may reuse cached assets. Browser settings can clear that cache, and private browsing may discard it when the session ends. A local workflow still needs enough available memory and processing power.`],
    ["Choose a background for the destination", `Use a transparent PNG when the cutout will sit on an existing design. The checkerboard preview represents transparency; it is not part of the downloaded image. Choose white for a simple catalog treatment, or select a custom color to check the subject against a specific background. Dark hair may look acceptable on white but reveal a light fringe on a dark color, so test both where relevant. The export combines your selected background with the current cutout. It does not invent missing parts of the subject, remove an object in the foreground, or recreate a studio lighting setup.`],
    ["Review edges before you share", `Inspect the result at the size where people will actually see it. Look for missing fine details, stray background patches, and soft edges that become obvious after resizing. Glass, smoke, fur, thin wires, and busy backgrounds are harder cases for automatic segmentation. If the result is unsuitable, try a clearer source photo or a dedicated editor with manual masking. Save the final PNG and open it separately to confirm transparency and dimensions. Do not close the tab before downloading: the workspace is temporary, and reloading does not provide a saved editing history. Use only images you have permission to edit and publish.`]
  ),
  "heic-converter": guide(
    ["Choose compatibility or smaller web files", `A phone photo saved as HEIC may not open in a recipient's software even though it looks normal on your device. This converter produces a new JPG or WebP image from supported HEIC data. JPG is a practical choice for broad compatibility with document editors, email workflows, and older software. WebP is useful when your destination explicitly accepts it. Select the format based on where the image will be used, not on the filename alone. Check the destination before converting a whole photo collection. Preparing one sample first lets you confirm acceptance, appearance, and download size with much less repeated work. Renaming a file from .heic to .jpg does not convert its internal image data and will not solve a decoding problem.`],
    ["Convert and compare a real example", `Choose a HEIC or HEIF file, select the output format and quality, and run the conversion. A higher quality setting generally retains more visible detail but may produce a larger download. Start with a moderate setting and inspect text, hair, and smooth gradients rather than assuming the highest value is always necessary. For a product photograph, compare the label lettering and edges at the intended display size. When a file contains multiple supported images, review each exported frame. A sequence of still exports is not the same as preserving an animated photo or every feature of the original container.`],
    ["Know what the conversion keeps", `The tool decodes image pixels and exports them through the browser's Canvas API. It does not promise to preserve camera metadata, location tags, depth information, editing history, or the original color-management behavior. Keep the HEIC original if those details matter to your archive. The downloaded JPG or WebP is a derivative intended for sharing or display. Repeatedly converting between lossy formats can accumulate artifacts, so return to the original when preparing a different version. Quality controls are encoder settings, not a promise that a particular percentage will yield a matching reduction in file size.`],
    ["Handle difficult files without uploading them", `An unsupported HEIF variant, damaged file, very large image, or device memory limit can cause conversion to fail. Read the error and try a smaller source before repeating the same operation. Some browsers and devices have different decoding and encoding capabilities. If a file still fails, export a compatible copy from the phone or photo application that created it. All selected image processing stays in the browser; there is no server fallback that silently receives your photo. Download successful results before leaving the page, and open the downloads once to confirm orientation, dimensions, and visible quality. The original file on your device remains unchanged.`]
  ),
  "zip-tool": guide(
    ["Choose extraction or archive creation", `A ZIP archive is a container that can hold several files and folders. Use extraction when someone has sent you a bundle and you need individual files. Use creation when you want to package several local files into one download. This tool handles ZIP archives, not every format that is commonly called an archive. RAR, 7z, encrypted ZIP files, and split multi-volume archives need a different workflow. Start by checking the filename and the source of the archive. A browser-based extractor does not make an unfamiliar attachment trustworthy, and it does not scan files for malicious content.`],
    ["Inspect before extracting", `Select a ZIP and review its entries before choosing what to download. Names, paths, and sizes help distinguish the document you need from unrelated assets. An archive may contain a top-level folder, nested folders, and hidden system files, so a long listing does not necessarily mean the data is duplicated. Download only the entries you intend to use. Extraction creates downloads; it does not run the contained files or install their contents. Open an extracted file only with an application appropriate to its type. A misleading extension can still disguise an unexpected document or executable.`],
    ["Create a useful bundle", `When creating a ZIP, choose the local files that belong together and review the selected list. Remove accidental additions before generating the archive. Give the downloaded archive a meaningful name that helps its recipient understand its purpose, such as project-assets or monthly-receipts. Files with identical names need distinct archive entry names rather than silently overwriting one another. Compression is most effective on repetitive data such as plain text. A bundle of JPEG photos or videos may barely shrink because those formats are already compressed. The value of the ZIP may be organization and a single download rather than a dramatic size reduction.`],
    ["Respect memory and expansion limits", `A small compressed archive can expand into much more data than its download size suggests. The tool checks limits before extraction and refuses oversized or suspicious inputs to protect the browser. Those checks are a practical safeguard, not a complete security assessment. Large legitimate archives can still exceed a phone's available memory. If an operation fails, try a smaller archive or use an established desktop archiver. Keep the source ZIP until you have checked the extracted files and their expected sizes. Selected data stays in local browser memory; closing the page discards the workspace, while anything you downloaded remains on your device until you remove it.`]
  ),
  "pdf-merger": guide(
    ["Build a reading order before merging", `Suppose you have a two-page cover letter and a three-page attachment. A useful combined PDF might begin with the cover letter, continue with the attachment, and end with a supporting page from another file. The merger lets you organize those individual pages into one output. Before selecting files, decide which pages belong in the final document and which can be omitted. A short outline saves repeated rearranging later. Keep the originals in a separate folder so you can recover a missing page or compare the result after export. The tool creates a new PDF and does not modify those source files.`],
    ["Arrange individual pages", `Select the PDFs you want to combine and inspect the page list. Each entry identifies its source document and source page, which is important when several files have similar names. Use the available position controls to move pages into the desired reading order. Removing a page from the output list does not delete that page from its original file. After each change, read the sequence from top to bottom. Check transitions between documents, especially when a cover page, appendix, or reverse-side scan must remain next to another page. The output follows the order in the workspace, not the alphabetical order of your filenames.`],
    ["Check document features separately", `Page copying is not the same as preserving every feature of a PDF. Bookmarks, document-level attachments, interactive form behavior, accessibility tags, and annotations may require separate review. Merging also creates a new document, so existing digital signatures do not retain their original cryptographic validity. This workflow rejects encrypted PDFs; obtain a permitted unencrypted copy from the owner rather than trying to bypass protection. Scanned pages remain scanned images unless another application performs OCR. Text that was not searchable in the source will not become searchable merely because the pages were placed in a new file.`],
    ["Export and verify the actual download", `Download the merged PDF, then open it in a PDF viewer outside the workspace. Confirm the total page count, the first and last pages, and every point where one source document joins another. Zoom in on small print and inspect pages with unusual sizes or rotation. If the PDF will be printed, review the viewer's page-size and scaling options before printing the whole document. Processing runs in the browser, so large scans may be limited by the device's memory. Try smaller batches if necessary. Do not close the tab until the download is complete, and retain the source documents until the final file has been checked.`]
  ),
  "json-formatter": guide(
    ["Start with valid JSON, not JavaScript", `JSON uses double-quoted property names, double-quoted strings, numbers, booleans, null, arrays, and objects. A JavaScript object literal can look similar while containing syntax JSON does not allow. For example, comments, single-quoted strings, and trailing commas are invalid JSON. Paste your text into the input editor and validate it before trying to use it in another system. The formatter reports parsing failures rather than guessing what you meant. That distinction matters when the text is configuration or a request payload: automatically repairing an ambiguous value can change the meaning of the data without making the change obvious.`],
    ["Format for reading or minify for transport", `Use formatting when you want indentation and line breaks that reveal nesting. Choose an indentation style that matches the project where the result will be used. A small example such as {"name":"Ada","active":true} becomes easier to scan when each property appears on its own line. Minification removes unnecessary whitespace around the parsed values. It does not compress strings inside the data and does not provide encryption. Copy the result or download it as a JSON file when you are satisfied. Changing the input requires a fresh operation so that an old result is not mistaken for a transformation of new text.`],
    ["Protect values that need exact fidelity", `This formatter uses JavaScript's JSON parser and serializer. Numbers therefore follow JavaScript's finite-precision number representation. Very large integer identifiers can be rounded, and an object's duplicate keys resolve to the last parsed value. If exact long identifiers or decimal representations matter, represent them as strings at the source and validate them with a system designed for the required precision. Formatting is not a byte-preserving process: whitespace changes, escaped characters can be normalized, and numeric notation can change. Keep an untouched original if you are comparing signatures, hashes, audit records, or a payload whose exact bytes have significance.`],
    ["Use local processing thoughtfully", `Your editor text is processed in the browser and is not sent to a formatting API. The workspace does not provide a persistent history or account-based recovery. Save a copy before reloading or closing the page. Local processing avoids a server upload, but it does not hide the text from someone looking at your screen, browser extensions with relevant access, or your own clipboard history. Avoid pasting secrets unless your device and environment are appropriate for the task. For a parsing error, check the surrounding quote marks, commas, and brackets. Fix one problem at a time and validate again before copying the final result into a live system.`]
  ),
  "qr-generator": guide(
    ["Choose a URL or WiFi payload", `A QR code stores data that a compatible scanner can read. For a web link, enter the full destination address, including https://, and confirm that the page opens normally before making the code. For WiFi sharing, enter the network name, security type, password where required, and whether the network is hidden. These are different payload formats: placing a network password in a normal URL field will not create a WiFi join code. Check every character carefully because a code can be perfectly readable while still containing an incorrect address or credential. Generation happens locally and does not require an account.`],
    ["Understand what is visible to a scanner", `A WiFi QR code is a convenient representation of connection details, not an encrypted vault. Anyone who can photograph or decode it can recover the embedded network name and password. Place it only where your intended audience can see it, and use a guest network where that fits your setup. URL codes likewise contain their destination address. A static code does not depend on a hosted redirect service from Localtools, so there is no subscription or expiration mechanism attached to the code itself. The destination website can still move, and a changed WiFi password makes the old code outdated.`],
    ["Export for a screen or print", `PNG is convenient for documents, messages, and ordinary screen display. SVG remains sharp when resized in a compatible design or printing application. Keep the light border around the QR pattern: that quiet zone helps scanners distinguish the code from nearby content. Avoid stretching it into a rectangle, cropping its edges, placing it over a busy photograph, or changing colors until the contrast becomes weak. Longer URLs and more data can produce a denser pattern that needs a larger display size. Error-correction settings provide different levels of redundancy, but they cannot compensate for an unreadably small or severely damaged image.`],
    ["Test the version people will actually use", `Scan the exported code with another device before distributing it. For a WiFi code, confirm that the device recognizes the intended network details. For a URL, verify the complete destination, including any path or query parameters. Then test again after placing the code in the final document or printing a sample. A code that scans from a large monitor may fail on a small, low-quality print. Keep a human-readable instruction nearby so people know what scanning will do. If credentials or destinations change later, generate and distribute an updated code rather than assuming an old printed code can update itself. Delete sensitive exported files when they are no longer needed.`]
  ),
  "word-counter": guide(
    ["Measure a draft without changing it", `Paste a draft into the editor to see word count, character count, sentence estimates, and reading time. These measurements answer different questions. A publication may impose a word limit, a form may restrict characters, and a presenter may need to estimate delivery time. Check which definition the destination uses before editing to match a number. A word counter is a measurement aid, not a spelling checker or an assessment of whether an argument is correct. Keep a copy of the original text if you plan to make substantial edits, and use the updated counts to compare versions intentionally.`],
    ["Distinguish characters from storage units", `A visible character is not always one JavaScript string unit. Combined accents and emoji can use several code points or UTF-16 code units while appearing as one symbol. This tool shows user-perceived character counts using browser segmentation where available and also reports UTF-16 units separately. Word boundaries depend on language and punctuation conventions, so another application's count may differ at the margins. Hyphenated words, apostrophes, abbreviations, and languages without spaces are common reasons. For a strict submission limit, treat the destination system's own count as authoritative and leave a small buffer instead of aiming for the exact last character.`],
    ["Interpret readability as an estimate", `Flesch Reading Ease and Flesch-Kincaid Grade Level use relationships between words, sentences, and estimated syllables. They are intended here as rough English-language indicators. A short technical term may be essential even if it makes a score less favorable, while a simple sentence can still communicate a misleading idea. Syllable estimation cannot handle every name, acronym, or pronunciation correctly. Very short samples are especially unstable because changing one word or sentence boundary can move the score sharply. Use a longer representative passage and compare revisions of the same kind of writing rather than treating a single number as a universal quality grade.`],
    ["Turn counts into a useful edit", `For a 600-word draft at 200 words per minute, the simple reading estimate is three minutes. Spoken delivery often needs extra time for emphasis, pauses, demonstrations, or audience questions. Adjust the words-per-minute setting to a pace appropriate for your reader or speaker, then rehearse important material with a timer. If readability seems difficult, look for long sentences carrying several ideas, undefined jargon, and paragraphs without a clear purpose. Improve those features rather than deleting necessary information solely to raise a score. Your text remains in browser memory, so save the revised draft before leaving the page. Copying or downloading it creates a local artifact under your control.`]
  ),
  "youtube-toolkit": guide(
    ["Use the right input for each job", `This workspace combines two creator tasks: finding a video's thumbnail images and cleaning subtitle text. For thumbnails, provide a supported YouTube URL or the video's eleven-character ID, then explicitly load the images. For transcript cleanup, paste captions or choose an SRT or VTT file that you already have. The tool does not fetch a transcript from a YouTube link and does not run a proxy or scraping service. Keeping those tasks separate avoids an important misunderstanding: a publicly viewable video does not mean that every caption track can be retrieved directly by a browser without additional permissions or services.`],
    ["Inspect available thumbnail resolutions", `YouTube serves thumbnail images through i.ytimg.com. Loading them sends requests to that service, including the selected video identifier and ordinary connection information. Your local subtitle text is not part of those requests. Available resolutions differ by video. A high-resolution URL may return a small fallback image or fail, so inspect the reported image dimensions rather than assuming every option exists. Choose an available resolution that suits the destination without unnecessary upscaling. A thumbnail that already contains text can become difficult to read when enlarged or recompressed, and a larger filename label is not proof of additional image detail.`],
    ["Download without a hidden server fallback", `The download control attempts to save the image using browser capabilities. Cross-origin restrictions can prevent that operation even when an image displays successfully. In that case, use the original-image link and your browser's Save image action. The tool does not send the request through a backend to circumvent those restrictions. Download availability also does not grant reuse rights. Use your own channel artwork, licensed material, or images for which you have permission. Before publishing, check the exact file you saved, its actual resolution, and whether its composition still works at the final display size.`],
    ["Clean captions and review the language", `An SRT file normally contains cue numbers, timestamp ranges, and caption lines. VTT can include additional header information and cue settings. Cleanup removes timing structure and supported markup to produce readable text; optional formatting can join lines or remove adjacent repeated caption text. Review the output around speaker changes, numbers, punctuation, and repeated phrases. A phrase repeated for emphasis should not always be removed, and caption line breaks do not necessarily mark paragraph boundaries. This is a text transformation, not a correction of transcription mistakes. Copy or download the cleaned text, keep the original subtitle file for timing information, and avoid closing the page before saving your work. Local captions are processed in memory and are not uploaded for cleanup.`]
  ),
  "percentage-calculator": guide(
    ["Choose the relationship you want to measure", `Percentage questions often sound similar while using different formulas. Finding twenty percent of a value is not the same as asking what percentage one value represents of another. Percentage change also needs an original value as its reference point. Select the relevant mode before entering numbers, and read the displayed formula to check the meaning of the result. For example, twenty percent of 250 is 50, while 50 as a percentage of 250 is twenty percent. Clear labels are more useful than a bare percentage because they preserve which number was the base of the calculation.`],
    ["Calculate change from the original value", `If a price rises from 80 to 100, the difference is 20 and the increase is twenty-five percent of the original 80. If it later falls from 100 back to 80, the decrease is twenty percent of the new starting value. Those percentages differ because the denominator changed. A zero original value makes ordinary percentage change undefined; the tool explains that case instead of displaying Infinity. Negative starting values can also make a conventional percentage-change interpretation confusing. Keep the underlying values visible and describe what changed in ordinary units whenever that is more informative than a percentage alone.`],
    ["Keep margin and markup separate", `Suppose an item costs 60 and sells for 100. Profit before any additional expenses is 40. Profit margin is 40 divided by the selling price of 100, or forty percent. Markup is 40 divided by the cost of 60, or approximately sixty-six point seven percent. Confusing these figures can lead to incorrect pricing targets. Include all relevant costs in the amount you enter if you want a broader cost basis. This calculator does not automatically add shipping, payment fees, tax, overhead, discounts, refunds, or the value of your time. Its result reflects the inputs and formula, not a complete business assessment.`],
    ["Check edge cases and rounding", `A selling price below cost produces a negative profit. A zero selling price makes margin undefined, while a zero cost makes markup undefined. These are mathematical boundaries, not software failures. Small floating-point rounding differences can appear with decimal inputs, so compare results at a sensible number of decimal places. Retain more precision during intermediate calculations and round when presenting the final amount. For important pricing, accounting, or contractual decisions, verify the result against the exact rules and figures that apply to the situation. The tool performs arithmetic locally, does not connect to financial accounts, and does not save a transaction history. Copy the values you need before resetting the workspace or leaving the page.`]
  ),
  "unit-converter": guide(
    ["Select a measurement family first", `Begin by choosing the kind of quantity you have: length, mass, temperature, area, volume, speed, time, or data storage. Then select the source and destination units and enter a finite numeric value. Units within a family describe the same physical or digital quantity using different scales. A kilometer can become meters, but it cannot become kilograms without information about something else. Keep units beside every value when transferring results into a document or spreadsheet. A number such as 100 is ambiguous by itself, and a missing prefix can cause an error much larger than any rounding difference.`],
    ["Use a simple conversion as a check", `One meter equals one hundred centimeters, and one kilometer equals one thousand meters. A sensible result should preserve that relationship as you scale the input. Area and volume use squared and cubed dimensions, so their conversion factors are not the same as the corresponding length factor. Speed combines distance and time, which means both parts matter. If a value seems unexpectedly large or small, check the selected family and units before questioning the arithmetic. Swapping the source and destination units should reverse the conversion relationship, but displayed rounding can prevent an exact visual round trip at extreme magnitudes.`],
    ["Distinguish decimal storage from binary storage", `A decimal gigabyte, written GB, contains 1,000,000,000 bytes. A binary gibibyte, written GiB, contains 1,073,741,824 bytes. Therefore one GiB is approximately 1.073741824 GB, not exactly one GB. The same distinction applies to KB and KiB, MB and MiB, and larger prefixes. Bits and bytes are another separate distinction: eight bits make one byte. A network speed expressed in megabits per second is not the same as megabytes per second. This tool converts stored quantities, not a promise of transfer performance; real download time also depends on connection conditions, overhead, and the server providing the data.`],
    ["Treat temperature and precision carefully", `Temperature conversions include offsets as well as scale factors. Zero degrees Celsius is thirty-two degrees Fahrenheit and 273.15 kelvin. A temperature difference uses a different interpretation from an absolute temperature reading, so this converter is intended for readings in the selected scale. Values below absolute zero are rejected. Other measurement families can accept negative numbers where they represent a meaningful signed quantity, but the interpretation remains your responsibility. Very large or tiny values may use scientific notation, and browser arithmetic has finite precision. Use an appropriate specialist method where certified measurement or exact decimal precision is required. All calculations run locally, and changing a selection immediately updates the result without contacting a conversion API.`]
  ),
};

export const categoryGuides: Record<ToolCategory, GuideSection[]> = {
  pdf: guide(
    ["Organize the document before its pages", `A useful PDF workflow begins with the final reader. Decide what that person needs to see first, what belongs together, and which supporting material can appear at the end. This suite currently provides the PDF Merger & Page Reorder tool for combining existing PDFs and arranging their individual pages. It is appropriate for assembling a reading packet, consolidating related statements, or placing a cover sheet ahead of an attachment. It is not a replacement for a complete PDF editor. Start with a small, clearly named set of source files, and keep untouched copies until the exported document has been reviewed.`],
    ["Follow a page-by-page workflow", `Select the source PDFs and inspect the page list rather than relying only on the order in which the files were chosen. A document can contain an unexpected blank page, a reversed scan, or several unrelated sections. Use each entry's source name and page number to arrange the intended sequence. For example, a cover sheet from one file may need to precede only the first section of another file rather than its entire contents. Removing an entry from the output does not change the original. After ordering, export the combined PDF and open the downloaded file in a separate viewer.`],
    ["Understand what page copying does not promise", `PDF is a container for more than visible pages. It can include forms, annotations, embedded files, bookmarks, accessibility information, encryption, and digital signatures. Copying pages into a new document does not guarantee preservation of every document-level feature. Existing digital signatures cannot retain the same cryptographic validity after the document is rebuilt. Encrypted inputs require a permitted unencrypted copy. A scan remains an image unless OCR is performed elsewhere; merging does not turn photographed text into searchable text. If any of these features matter, test a representative file before relying on the workflow for a larger batch.`],
    ["Keep privacy and verification connected", `The available PDF tool processes selected files inside the browser. There is no document upload endpoint or remote processing queue. That reduces the need to transmit a document, but the local device still needs sufficient memory and a trustworthy working environment. Large scanned pages can use much more memory than their file sizes suggest. Try smaller batches if the browser struggles. Before sharing the output, check the page count, transitions between documents, orientation, readable text, and any form fields you expect to use. Keep the source files so an incorrect merge can be rebuilt. Downloaded PDFs remain on your device after the temporary browser workspace is closed.`]
  ),
  image: guide(
    ["Choose between changing a format and changing an image", `A HEIC conversion and a background removal solve different problems. Conversion makes an image available in another file format, while background removal changes which parts of the image remain visible. The current image suite includes both workflows. If a phone photo cannot be opened by the next application in your process, convert it to a supported JPG or WebP first. If the subject needs to sit on a new background, use the background remover on a supported image. Keep the original source separately so you can create another derivative without repeatedly editing an already compressed output.`],
    ["Work from the destination backward", `Decide where the final image will appear before choosing settings. A document attachment may favor JPG compatibility. A website that supports WebP may benefit from that format. A cutout placed in a design usually needs a PNG with transparency. For a product listing, inspect the platform's current requirements directly rather than assuming every marketplace accepts the same background or dimensions. Start with one image and verify the entire workflow before processing a group. Compare text, fine edges, color, and orientation at the final display size. A visually acceptable preview is useful, but the downloaded file is the artifact you will actually share.`],
    ["Understand local AI and image conversion", `Background removal downloads a model and runtime before processing the chosen photo on your device. The first run may therefore be slow even though no photo is being uploaded. HEIC conversion uses a browser decoder and Canvas export to create a new image. These operations depend on device resources and browser capabilities. They do not preserve every feature of a camera file, including all metadata or container-specific information. Automatic segmentation also makes predictions rather than applying a perfect physical boundary. Hair, glass, shadows, and similar foreground and background colors deserve careful inspection before the result is used commercially or publicly.`],
    ["Keep a small, repeatable quality checklist", `After export, open the image separately and verify its extension, dimensions, orientation, and visual quality. Put a transparent cutout against both a light and a dark background to reveal halos or missing edges. Check that any custom background color is the intended one, and confirm that a checkerboard preview has not been mistaken for actual image content. Avoid repeatedly converting lossy files when an original is available. If a large image fails, try a smaller source or use the application that created it to export a compatible version. Selected image content remains local, while downloaded model assets can be cached by the browser and thumbnail or image exports remain on your device.`]
  ),
  media: guide(
    ["Plan a media workflow around the output", `Video and audio tasks need a clear destination: a short clip for a presentation, a smaller file for sharing, a muted video, or an audio-only export. Those goals use different operations and may require different codecs. Most media tools in this suite are coming soon: video editing and audio conversion need FFmpeg compiled to WebAssembly, which is added in a later phase. Subtitle timing tools that only work on text are live now. The current YouTube creator toolkit can help with thumbnail images and locally supplied subtitle text, but it does not edit the underlying video. The distinction prevents a simple caption or thumbnail task from being mistaken for a complete media-production workflow.`],
    ["Separate a container from a codec", `A filename extension such as MP4 describes a container rather than every detail of the media inside it. The container can hold video, audio, metadata, and other streams encoded in different ways. A browser may support a container but still lack support for a particular codec or profile. Renaming the extension does not transcode the content. Before choosing a future conversion tool, identify the source format and the requirements of the destination application. Keep an untouched source copy. A conversion that changes compression settings can affect quality, and repeating that process on an already compressed file can make artifacts more visible.`],
    ["Budget time and memory for browser processing", `Media operations can require substantial memory because compressed files must often be decoded into much larger working data. A short high-resolution clip may therefore be demanding even when its download size seems modest. Browser WebAssembly runs code on the user's device; it does not create unlimited capacity or guarantee hardware acceleration. Background tabs, low battery modes, and other applications can affect performance. For any future browser media tool, begin with a short representative sample, read the stated size limits, and keep the tab open until the export is saved. A successful small test is a better guide than a promise based only on file size.`],
    ["Review timing as well as picture quality", `A finished media export needs more than a visual glance. Check the beginning and ending, audio synchronization, transitions, orientation, and whether any captions still line up. Listen through a short sample with headphones and test the file in the destination player. If the task is only to clean captions for reading, keep the original SRT or VTT so its timing information is not lost. Plain-text transcript cleanup intentionally removes that structure. As this category expands, only tools with working browser implementations will appear as available entries. Until then, use the existing creator tools for their stated purpose or a suitable local media application for editing and conversion.`]
  ),
  dev: guide(
    ["Use a focused tool for a specific transformation", `The developer suite currently provides a privacy-first JSON formatter and a ZIP extractor and creator. One helps you inspect structured text; the other organizes files into or out of an archive. Both run their operations in the browser rather than sending the input to a processing API. Choose the tool based on the artifact you need at the end: readable JSON, compact JSON, an extracted file, or a new ZIP. Avoid using a transformation merely because it is available. A useful development workflow preserves the original input and makes the intended change easy to verify afterward.`],
    ["Validate structure before relying on presentation", `Indented JSON looks more readable, but indentation does not establish that the values are correct. First confirm that the text is valid JSON, then inspect nesting, property names, and the expected data types. Standard JSON excludes comments, trailing commas, and unquoted keys. The browser parser also has numeric-precision limits and resolves duplicate keys to the last parsed value. For long identifiers, exact decimal representations, or signed payloads, preserve the source and use a format that retains the required fidelity. Minification changes representation; it does not encrypt a payload or prove that another application will accept its contents.`],
    ["Treat archives as containers with boundaries", `A ZIP can include many files, nested folders, and names that look similar. Inspect the entry list before extracting, and download only what you need. A local extractor does not automatically make the contents safe or run them for you. When creating an archive, review filenames and avoid accidental duplicates or unrelated files. Already compressed photos and videos may gain little from another compression layer. The tool applies practical limits to input size and expansion to protect browser memory. If a legitimate archive exceeds those boundaries, use a desktop archiver instead of repeatedly attempting the same operation in a constrained tab.`],
    ["Keep sensitive development data local", `Local processing avoids transmitting the selected JSON or files to a formatter or archive service. It does not erase ordinary device risks, including screen sharing, clipboard history, browser extensions, or downloaded artifacts left in a shared folder. Use sample data when testing unfamiliar workflows and keep secrets out of examples or screenshots. Save a successful output before reloading because the workspace is temporary. Then verify it with the system that will consume it: parse the downloaded JSON, inspect the expected keys, or open the ZIP with another archive viewer. A transformation is complete when the artifact behaves as intended, not merely when the interface displays a success message.`]
  ),
  crypto: guide(
    ["Begin with the data a recipient will read", `The first tool in this category is the WiFi & URL QR Generator. It turns a web address or network connection details into a scannable image. This is an encoding task, not encryption. The distinction is central to a privacy-conscious workflow: a convenient representation of information does not automatically conceal that information. The category is designed to accommodate future browser encoding and network utilities, but only the listed QR tool is currently available. There is no general encryption workbench, network scanner, or remote diagnostic service behind this page. Choose a listed capability and inspect its input and output formats before using it.`],
    ["Keep WiFi sharing intentional", `A WiFi code contains the network name, security type, and any supplied password. Someone who can scan or decode the image can recover those details. Use a guest network when that is appropriate, place the code where only intended users can access it, and replace the image if credentials change. Hidden-network settings must match the network configuration; they do not make the printed code private. Test the exported image with a compatible device before distributing it. A scanner's ability to read the pattern and the device's ability to connect to the network are separate checks.`],
    ["Make URL codes understandable", `A URL code should lead to a destination the scanner expects. Include a short human-readable label explaining the destination or action. Enter the complete address, check its scheme and host, and open it yourself before creating the code. Static QR codes do not require a Localtools redirect service, but the target website still controls what visitors see. If the destination later changes or disappears, the printed code cannot rewrite itself. Keep a clear quiet zone around the pattern and use sufficient contrast. A dense code may need more physical space than a short URL, especially in a printed layout.`],
    ["Apply the same distinction to future utilities", `Encoding, hashing, encryption, and validation are different operations with different purposes. Encoding changes representation; hashing produces a digest; encryption uses a key to protect recoverable data; validation checks specified rules. A future tool should make that purpose explicit rather than grouping every transformation under a security claim. For the current QR workflow, save PNG for ordinary use or SVG for scalable placement, then test the final printed or displayed version. The generator processes inputs locally and does not retain credentials in an account. Your downloaded code and clipboard can still contain sensitive information, so handle those artifacts with the same care as the text they represent.`]
  ),
  youtube: guide(
    ["Keep creator tasks separate from account automation", `This suite currently helps with thumbnail images and subtitle text. It does not sign in to a YouTube account, publish videos, schedule uploads, collect analytics, or fetch a transcript through a proxy. Those boundaries matter because creator workflows often mix several very different actions under the word automation. Start by deciding whether you need an image asset or readable text from captions you already possess. A browser can perform the local cleanup directly, while thumbnail images are requested from YouTube's image service. Neither workflow requires you to provide an account password or an API key to Localtools.`],
    ["Choose a thumbnail that really exists", `Provide the video URL or identifier and load its thumbnail options. Standard quality names are useful shortcuts, but not every video supplies every resolution. The tool inspects loaded dimensions to help distinguish an actual larger image from a fallback. Select a size appropriate for the intended use and avoid upscaling a small thumbnail merely because a larger frame is available in your design. Check the saved file, not just the preview. Image requests go to i.ytimg.com and reveal the requested video identifier and ordinary connection data to that service; local caption text is not included in those requests.`],
    ["Turn subtitle structure into readable text", `SRT and VTT files combine text with timing information and sometimes cue identifiers or formatting. The cleaner removes that structure so you can edit or read the words as ordinary text. Paste a small sample first and review how line breaks, speaker changes, and numeric lines are handled. Optional deduplication can help with repeated rolling captions, but repetition can also be intentional. Retain the original timed file because plain text cannot reconstruct its original synchronization. Cleanup does not correct inaccurate transcription, identify speakers reliably, or translate the content. Read the output for meaning before reusing it in a script or article.`],
    ["Respect browser limits and reuse rights", `A browser may display a remote image while refusing a direct cross-origin download. When that happens, open the original image and use the browser's save action; this site does not route the request through a hidden backend. A downloadable thumbnail is also not permission to republish someone else's artwork. Use your own assets, licensed material, or content you are authorized to reuse. Before leaving the workspace, download the cleaned transcript or image and verify the result. Choose descriptive filenames and keep source material for comparison. Future tools will be listed only as their actual browser functionality becomes available, rather than appearing as empty interfaces that promise account automation.`]
  ),
  text: guide(
    ["Match the measurement to the writing task", `A writing limit may refer to words, visible characters, storage units, or reading duration. Those are different measurements, so begin with the rule you are trying to satisfy. The current text suite includes the Word & Readability Counter. Paste a representative draft and review its counts before editing. A compact social caption needs a different evaluation from a long technical guide or a spoken script. The counter helps make those tradeoffs visible, but it does not verify facts, judge the strength of an argument, or replace an editor who understands the audience and purpose of the text.`],
    ["Expect reasonable differences between counters", `Word segmentation depends on punctuation, language, and the conventions used by the software. Hyphenated phrases, abbreviations, contractions, and languages without spaces can produce different totals in different applications. Character counting has similar subtleties: a visible emoji or accented character can contain several underlying string units. This tool distinguishes user-perceived characters from UTF-16 units where browser support permits. For a strict form or publication limit, the destination system's count is the final reference. Leave a small margin rather than assuming that matching a local count exactly guarantees acceptance by a separate service with different counting rules.`],
    ["Use readability to locate friction", `English readability formulas summarize sentence length and estimated syllable patterns. They can help identify a draft that became denser after revision, but they do not measure accuracy, usefulness, tone, or empathy. Technical names and necessary specialist vocabulary can raise a score without making the writing inappropriate for its audience. Short samples can fluctuate sharply, and automatic syllable estimates are imperfect. Compare similar passages and inspect the actual sentences that feel difficult. Splitting a sentence with several ideas, defining a term, or choosing a concrete example is usually more useful than chasing a target number without understanding what changed.`],
    ["Check reading time against real delivery", `A simple reading-time estimate divides the word count by a selected words-per-minute rate. At 200 words per minute, an 800-word passage takes about four minutes under that assumption. A narrated demonstration, speech, or lesson needs additional time for pauses, visual attention, and audience response. Rehearse important material with a timer rather than treating the estimate as a booking duration. The text is processed locally and the workspace does not retain a persistent draft history. Save the revised version before closing the page. If the material is sensitive, remember that local processing does not remove risks from screen sharing, clipboard history, or files stored on a shared computer.`]
  ),
  calculator: guide(
    ["Choose a formula before entering numbers", `This category contains the Percentage & Profit Margin calculator and the Unit & Data Storage converter. Both are useful when the relationship between values is known and you want a clear result without a spreadsheet. First identify what the result should represent. A percentage share, a percentage change, a profit margin, and a markup use different denominators. A unit conversion requires quantities from the same measurement family. Writing the question in words before selecting a mode helps prevent an apparently precise answer to the wrong question. Keep units and labels attached to the values you copy from the result.`],
    ["Use an example to confirm the interpretation", `An item bought for 60 and sold for 100 produces a difference of 40. Dividing by the selling price gives a forty-percent margin; dividing by cost gives roughly sixty-six point seven percent markup. Neither number is interchangeable with the other. Similarly, a change from 80 to 100 is a twenty-five-percent increase, while the reverse change is a twenty-percent decrease. The reference value changes. Check these relationships with a simple example when you are unfamiliar with a mode, then apply the same formula to your actual inputs. Include relevant costs yourself rather than assuming the calculator knows them.`],
    ["Treat prefixes and temperature with care", `A decimal GB contains one billion bytes, while a binary GiB contains 1,073,741,824 bytes. A byte contains eight bits. These distinctions explain many apparent disagreements between storage figures and network-rate labels. Temperature readings also require more than a multiplication factor: Celsius, Fahrenheit, and kelvin have different reference points. Area and volume conversions use squared and cubed dimensions, so a length factor alone is insufficient. Select the measurement family and both units explicitly. If a result is unexpectedly large or small, check those selections before changing the input to make the answer look familiar.`],
    ["Recognize mathematical and practical limits", `Division by zero makes some percentages undefined, and a temperature below absolute zero is not a valid reading. The tools show an explanation instead of treating those cases as ordinary results. Browser arithmetic also has finite precision, so very large values, tiny values, and repeated decimal operations can introduce rounding differences. These calculators do not access financial accounts, live prices, tax tables, or a measurement-certification service. Verify important decisions using the complete rules and data applicable to your situation. Processing stays local, and there is no saved calculation history. Copy the inputs, formula, units, and result together when you need a record that another person can understand and reproduce.`]
  ),
  data: guide(
    ["Define the table before transforming it", `A useful data workflow starts with a clear table: what each row represents, what each column means, and which values are allowed to be missing. CSV tools that work on plain text are live in this suite. Excel files and in-browser SQL need extra engines (SheetJS and sql.js) and are coming soon. The current developer suite can format JSON or package files into ZIP archives, but those operations do not validate a dataset or execute queries. Keep this distinction in mind when choosing a tool: a file that opens successfully is not necessarily a correctly interpreted table.`],
    ["Watch for values that resemble something else", `Spreadsheet applications may reinterpret identifiers as numbers, dates, or formulas. A code with leading zeros can lose them if treated as a number, and a long identifier can exceed a program's exact numeric precision. A date such as 03/04/2026 is ambiguous without a stated convention. Before importing or converting data, identify columns that should remain text and choose an unambiguous date representation. Keep the source file unchanged so you can detect accidental transformations. For a future CSV workflow, also check delimiter, character encoding, quote handling, and whether embedded line breaks belong inside a field rather than starting a new row.`],
    ["Use small samples to test assumptions", `Start with a sample that includes ordinary rows and difficult cases: missing values, commas inside text, non-English characters, duplicate identifiers, and the longest expected fields. Write down the expected row count and a few values that must survive unchanged. A successful conversion should preserve those expectations or clearly explain any deliberate changes. For future SQL analysis, distinguish filtering from deleting and aggregation from raw-row inspection. A total can look plausible even when duplicate rows were counted twice. Reconcile counts and representative records before accepting a transformed dataset, especially when another person will use it to make decisions.`],
    ["Keep browser analysis bounded and reviewable", `Local processing can avoid uploading a dataset, but large tables still consume memory when parsed, indexed, or copied. A compressed or compact file may expand considerably in memory. Begin with manageable inputs and read the stated limits of any tool before use. Sensitive columns deserve care even on a local device because downloaded results, clipboard history, and shared screens can expose them. This category will show actual working tools as they are implemented; it does not currently offer a hidden database or cloud storage service. Until then, use a suitable local spreadsheet or database application, preserve a backup, and document the transformations needed so the workflow can later be reproduced and checked.`]
  ),
  finance: guide(
    ["Master self-employment and income tax brackets", "Understanding freelancer and contractor taxation begins with separating self-employment obligations from regular income taxes. In the United States, independent 1099 contractors pay self-employment tax at a statutory rate of 15.3% on 92.35% of their net business earnings, which covers federal Social Security and Medicare contributions. Above that baseline, progressive federal tax brackets apply to taxable income after standard or itemized deductions. State income tax rules introduce additional variation across jurisdictions, ranging from states with zero personal income tax like Texas, Florida, and Washington to progressive systems with top marginal rates exceeding 10% in California and New York. Modeling both layers accurately ensures realistic projections of true take-home earnings and prevents unexpected year-end surprises when filing annual tax returns."],
    ["Leverage legitimate deductions and the QBI pass-through", "Net taxable earnings reflect gross business receipts minus allowable ordinary and necessary business expenses. Common deductions include equipment depreciation, professional software subscriptions, home office allocations, travel, health insurance premiums, and retirement contributions. Under current federal tax provisions, eligible self-employed individuals and pass-through entities may also qualify for the Section 199A Qualified Business Income deduction, which permits deducting up to 20% of qualified business income from taxable income subject to statutory phaseout thresholds. Factoring in qualified deductions reduces effective tax rates significantly and prevents overestimating annual tax burdens during budget planning and financial goal setting."],
    ["Schedule quarterly estimated tax payments to avoid penalties", "Because independent contractors and business owners do not have employers withholding taxes from paychecks, the Internal Revenue Service requires quarterly estimated payments using Form 1040-ES. The standard safe harbor rules mandate paying at least 90% of the current year liability or 100% of the prior year tax liability (110% for high earners) distributed across the four statutory payment due dates in April, June, September, and January. Calculating quarterly installments in advance enables setting aside adequate cash reserves in high-yield accounts, preventing cashflow disruptions, cash crunches, and statutory underpayment interest penalties. Regular monitoring helps adapt payments as your monthly revenue fluctuates throughout the fiscal year."],
    ["Maintain complete data privacy for sensitive earnings", "Financial modeling involves confidential income details, business revenues, and personal filing statuses that should remain private. All calculations in this financial suite execute entirely inside your local browser using client-side arithmetic. No income numbers, deduction totals, or state selections are ever transmitted across external networks or stored on remote servers. You can run unlimited financial scenarios with complete privacy, keeping your business records and tax planning confidential on your own machine. Always consult a certified public accountant or qualified tax professional for binding tax filings and personalized advice tailored to your specific situation."]
  ),
  "real-estate": guide(
    ["Evaluate the total true cost of homeownership beyond principal and interest", "A monthly mortgage payment encompasses significantly more than raw principal and interest amortization. Real estate ownership requires budgeting for property taxes, homeowner hazard insurance, and Private Mortgage Insurance (PMI) on conventional loans with down payments below 20%. In many jurisdictions, property taxes and insurance escrow add hundreds or thousands of dollars to monthly housing outflows. Furthermore, homeowners must account for ongoing maintenance reserves, typically estimated at 1% to 2% of total property value annually, alongside municipal assessments and homeowners association dues. Calculating the full PITI breakdown provides an accurate assessment of long-term affordability and household debt-to-income limits before making binding purchase offers."],
    ["Track loan-to-value milestones and automatic PMI cancellation", "Borrowers who put down less than 20% on conventional residential mortgages are generally assessed private mortgage insurance premiums to protect lenders against borrower default. Under the federal Homeowners Protection Act of 1998, homeowners have the statutory right to request PMI cancellation once their loan-to-value ratio reaches 80% of the original purchase price or appraised value, provided payments remain in good standing. Furthermore, mortgage servicers are legally required to automatically terminate borrower-paid PMI when the loan balance is scheduled to reach 78% of the original property value. Monitoring your amortization schedule allows you to identify the precise calendar month when equity reaches these statutory cancellation thresholds, potentially saving thousands in unnecessary premiums."],
    ["Analyze long-term rent versus buy financial break-even horizons", "Deciding whether to purchase residential property or continue renting involves far more than comparing a monthly mortgage payment against monthly rent. A robust financial model evaluates compounding home equity and long-term property appreciation against historical rent inflation, closing transaction costs (typically 2% to 5% at purchase and 6% to 8% at sale), and property tax escalation over time. Crucially, the model must account for the opportunity cost of capital: investing a substantial down payment and transaction fees into diversified index funds often generates competitive compounding returns over multi-year horizons. The break-even horizon identifies the exact holding period required for ownership equity to outpace renting and disciplined investing in public financial markets."],
    ["Model rental property investment cashflow and debt coverage", "Evaluating residential income properties, duplexes, or short-term vacation rentals requires rigorous cashflow analysis. Critical performance metrics include Capitalization Rate (Cap Rate), Cash-on-Cash Return, Gross Rent Multiplier, and Debt Service Coverage Ratio (DSCR). Prudent underwriting accounts for vacancy allowances (typically 5% to 8%), ongoing property management expenses, capital expenditure reserves for major building systems, and localized tenant turnover expenses. Generating transparent amortization and cashflow tables enables investors to stress-test purchase prices, financing terms, and projected rental rate adjustments before committing capital to illiquid physical real estate assets."]
  ),
  insurance: guide(
    ["Calculate life insurance coverage requirements using the DIME formula", "Determining the appropriate face amount for term life insurance requires a structured methodology rather than arbitrary rule-of-thumb multiples of annual salary. The DIME framework provides an established personal finance approach by systematically summing four primary obligations: Debt obligations such as personal loans and consumer credit, Income replacement multiplied by the duration dependents need financial support, Mortgage balance payoff, and Education funding for surviving children. Subtracting existing liquid savings, retirement accounts, and current death benefits from this aggregate total determines the net term life coverage necessary to safeguard your family against catastrophic loss of household income. This structured evaluation prevents leaving dependents underinsured or paying excessive premiums for surplus coverage."],
    ["Differentiate term life protection from cash-value policies", "Choosing between term life insurance and permanent cash-value products like whole life or universal life represents a fundamental financial decision for working households. Term life provides pure insurance protection for a specified window (typically 10, 20, or 30 years) at a fraction of the cost of permanent policies, making it ideal for income replacement during peak earning and family-rearing years. Permanent insurance incorporates an internal savings or investment component paired with substantially higher premium expenses, opaque internal fees, and surrender charges. For most working households, combining affordable level-term coverage with independent long-term investing in low-cost index funds offers superior financial flexibility, transparency, liquidity, and wealth accumulation over decades."],
    ["Evaluate auto loan refinancing terms and total interest liabilities", "Refinancing an automotive loan can reduce monthly debt payments by securing a lower annual percentage rate or altering the amortization schedule. However, extending the repayment term to achieve a cosmetic reduction in monthly payments often inadvertently increases the cumulative interest paid over the life of the vehicle, increasing the likelihood of negative equity or being upside-down on the loan. A comprehensive refinancing analysis compares the revised monthly cashflow requirement against total interest savings over the remaining term, factoring in prepayment options and any lender origination fees to ensure genuine financial improvement rather than short-term cashflow relief that proves more expensive in the long run."],
    ["Protect confidential household information from aggressive lead brokers", "Researching life insurance coverage, vehicle refinancing, and financial protection frequently exposes consumers to aggressive telemarketing networks, unsolicited sales calls, and third-party data brokers. The insurance planning tools in this suite operate entirely within your browser tab, without requesting personal identifying information such as full legal names, contact numbers, email addresses, or vehicle identification numbers. All calculations and scenario evaluations occur locally on your device, empowering you to analyze coverage needs and rate comparisons privately before initiating formal applications with licensed carriers, brokers, or independent financial advisors."]
  ),
  business: guide(
    ["Master merchant payment processing fees and credit card interchange", "Operating an e-commerce storefront, consulting agency, or digital services business requires actively managing payment gateway processing overhead and merchant discounts. Payment processors like Stripe, PayPal, and Square typically assess a combination of percentage transaction fees and fixed per-charge costs, such as 2.9% plus 30 cents per successful card transaction. Transactions involving international credit cards, currency conversion, American Express processing, chargeback mediation, or dispute resolution incur additional surcharges. Failing to account for these processing deductions can substantially erode gross product margins, especially for low-ticket transactions or high-frequency recurring billing where fixed per-transaction fees represent an outsized percentage of total receipts, net deposits, and monthly operating revenues."],
    ["Calculate reverse fee pricing to guarantee exact net client receipts", "When issuing invoices for freelance services, contract retainers, or commercial deliverables, businesses often seek to receive an exact net figure after payment processing deductions. Standard percentage markups fail to achieve this outcome because processor percentage fees apply to the final gross invoiced sum rather than the initial net amount. Utilizing an exact reverse fee calculation formula ensures that you bill the precise gross sum required so that, after percentage and fixed fees are withheld, the resulting net deposit matches your target revenue to the penny. This mathematical precision eliminates unexpected shortfalls in business cashflow, tax reserves, and accounting ledger reconciliations across client accounts."],
    ["Track vital SaaS unit economics, burn rate, and capital runway", "Building and scaling a sustainable subscription software business depends on disciplined monitoring of core unit economics, cohort retention, and operating metrics. Critical benchmarks include Customer Lifetime Value (LTV), Customer Acquisition Cost (CAC), Average Revenue Per Account (ARPA), and the CAC Payback Period. A healthy subscription model targets an LTV to CAC ratio of at least 3:1 alongside a payback window under twelve months. Furthermore, monitoring monthly gross revenue against operating expenses yields your exact net burn rate, determining how many months of operational runway remain before requiring additional capital injections, venture funding rounds, or self-sustaining profitability milestones in competitive software markets."],
    ["Model Amazon FBA fulfillment size tiers and net inventory margins", "Selling physical merchandise through the Amazon Fulfillment by Amazon (FBA) ecosystem requires navigating intricate fee matrices that directly influence inventory profitability. Sellers must account for category referral fees (typically ranging from 8% to 15%), dimensional weight packaging calculations, and size-tiered fulfillment fees covering picking, packing, and carrier delivery. Additionally, marketing spend via Sponsored Products (ACoS), long-term storage fees, and customer return allowances must be factored into unit economics. Running comprehensive margin modeling prevents stockouts of low-margin inventory and guides pricing decisions to ensure sustainable return on investment across competitive high-volume marketplace channels."]
  ),
  marketing: guide(
    ["Calculate advertising ROAS and break-even customer acquisition costs", "Evaluating digital performance advertising across platforms like Google Ads, Meta Ads, and TikTok Ads requires distinguishing between gross revenue metrics and genuine profitability. Return on Ad Spend (ROAS) calculates total generated revenue divided by advertising spend, providing a baseline measure of campaign efficiency. However, a high ROAS does not ensure positive operating income if underlying product costs, shipping, merchant fees, and fulfillment expenses are neglected. Determining your exact break-even ROAS establishes the minimum conversion performance needed to avoid operating at a deficit, while identifying your maximum allowable Cost Per Acquisition (CPA) guarantees profitable ad scaling across paid media channels and client ad accounts over sustained multi-channel marketing campaigns without wasting capital."],
    ["Determine maximum target CPA based on unit gross margins", "Establishing target acquisition bids without knowing product margins frequently leads to unprofitable ad spend and depleted marketing budgets. By multiplying average order value (AOV) by your gross profit margin percentage, you determine the contribution margin available to finance customer acquisition. Setting your target CPA below this contribution threshold ensures that every acquired customer delivers net operating profit to your balance sheet. This disciplined target CPA modeling allows growth marketers and media buyers to configure automated bidding algorithms, target cost caps, and performance max campaigns with statistical confidence rather than speculative guessing, emotional reactions, or costly trial-and-error spending on untested creative concepts across ad platforms."],
    ["Project digital publisher ad revenue across geographic tiers", "Monetizing web properties, content hubs, and digital publications through display advertising networks such as Google AdSense, Raptive, and Mediavine relies heavily on audience demographics and traffic origin. Advertisers in Tier-1 countries (United States, United Kingdom, Canada, Australia) bid substantially higher Cost Per Mille (CPM) rates due to higher consumer disposable income and conversion rates. Modeling pageview volume, average pageviews per session, niche audience multipliers, and Tier-1 geographic traffic percentages produces dependable Revenue Per Mille (RPM) and monthly income projections for digital publishers seeking sustainable monetization, editorial expansion, team hiring, and predictable recurring ad revenues over multiple quarters."],
    ["Model paid media campaigns with zero ad network tracking", "Designing media budgets, forecasting revenue, and evaluating performance metrics should not compromise your strategic business data or confidential marketing roadmaps. The advertising calculators and marketing modeling utilities in this suite run exclusively inside your browser using client-side JavaScript. No campaign budgets, projected revenues, customer numbers, conversion targets, or proprietary acquisition figures are ever tracked, monitored, or transmitted to external advertising networks or analytics servers, allowing performance marketers, growth leads, and agency strategists to plan campaigns in complete confidentiality without competitive intelligence leaks, tracking cookies, or unwanted advertising surveillance."]
  ),
  legal: guide(
    ["Generate compliant privacy policies for GDPR, CCPA, and global regulations", "Contemporary digital privacy statutes such as the European Union General Data Protection Regulation (GDPR), California Consumer Privacy Act (CCPA), and California Online Privacy Protection Act (CalOPPA) require digital properties to publish transparent disclosures regarding data collection practices. Website operators must clearly disclose the categories of personal data collected, third-party analytics integrations, cookie usage, advertising tracking, data retention schedules, and statutory data subject rights including opt-outs and erasure requests. Utilizing an interactive legal generator produces tailored Markdown and HTML policy documents that satisfy statutory requirements without expensive legal overhead, recurring subscription fees, or external third-party dependencies hosted on your production website, web application, or corporate marketing pages."],
    ["Audit web accessibility and color contrast against WCAG 2.2 standards", "Digital inclusivity and compliance with modern disability regulations such as the Americans with Disabilities Act (ADA) and European Accessibility Act (EAA) demand adherence to Web Content Accessibility Guidelines (WCAG 2.2). Ensuring adequate visual contrast between text and background elements is essential for low-vision readability across desktop and mobile displays. The WCAG contrast standard specifies a minimum contrast ratio of 4.5:1 for normal text and 3:1 for large typography under Level AA compliance, and 7:1 for normal text under Level AAA. Auditing color palettes locally ensures design compliance and provides compliant hex recommendations for design systems, front-end developers, product designers, and production user interfaces across diverse devices and operating systems."],
    ["Create formal client invoices and commercial nondisclosure agreements", "Independent consultants, software engineers, professional agencies, and commercial contractors require standard commercial agreements and billing instruments to conduct business smoothly and protect trade secrets. Generating professional, mathematically verified PDF invoices with multi-currency support (USD, GBP, EUR, CAD, AUD), structured itemization, payment terms, and tax calculations establishes clear commercial documentation and speeds client payment processing. Similarly, drafting bilateral or unilateral non-disclosure agreements (NDAs) protects confidential trade secrets, business concepts, proprietary technical workflows, and intellectual property before entering exploratory commercial discussions, vendor evaluations, or technical partnerships with prospective enterprise clients, investors, and external contractors."],
    ["Redact confidential documents permanently using client-side canvas flattening", "Redacting sensitive records, financial statements, medical files, or personal identifying information from PDF documents requires permanent data destruction rather than superficial visual overlays. Simply drawing a black rectangle over text in basic PDF viewers often leaves underlying textual data recoverable through text selection, copy-pasting, search indexing, or graphic export. True local redaction flattens the targeted page area into pixel-level canvas rasterization before rebuilding the output document, guaranteeing that sensitive numbers, Social Security numbers, banking details, and confidential text are permanently destroyed before client distribution or public records filing in legal and administrative proceedings."]
  ),
};

